A layout renders this navigation. What happens when a user clicks "Contact"?

```tsx
import Link from 'next/link'

export default function Nav() {
  return (
    <nav>
      <Link href="/blog">Blog</Link>
      <a href="/contact">Contact</a>
    </nav>
  )
}
```

Users report "Could not save" even though their invoices are saved. What is the bug?

```ts
'use server'
export async function save(prev: State, formData: FormData) {
  try {
    await db.invoice.create({ data: parse(formData) })
    revalidatePath('/invoices')
    redirect('/invoices')
  } catch (e) {
    console.error(e)
    return { error: 'Could not save' }
  }
}
```
